<?php
declare(strict_types=1);
try { require (getenv('UNIQUE_CRM_PRIVATE_DIR') ?: dirname($_SERVER['DOCUMENT_ROOT']).'/.unique-tailoring-crm').'/app.php';securityHeaders();startAdminSession(); }
catch(Throwable $e){http_response_code(503);exit('Customer register is not configured. Please contact the site administrator.');}
$error='';$notice='';$search=trim((string)($_GET['q']??''));$area=trim((string)($_GET['area']??''));$status=(string)($_GET['status']??'');$customerId=max(0,(int)($_GET['customer']??0));
function options(array $values,string $selected=''): string { $s='';foreach($values as $v)$s.='<option'.($v===$selected?' selected':'').'>'.h($v).'</option>';return $s; }
function input(string $name,string $label,string $value='',bool $required=false,string $type='text',int $max=160): string { return '<label>'.h($label).'<input name="'.h($name).'" type="'.$type.'" maxlength="'.$max.'" value="'.h($value).'"'.($required?' required':'').'></label>'; }
try {
 if($_SERVER['REQUEST_METHOD']==='POST'){
 checkCsrf();$action=(string)($_POST['action']??'');
 if($action==='login'){
 throttle('login',5,900);if(!hash_equals($config['admin_username'],(string)($_POST['username']??''))||!password_verify((string)($_POST['password']??''),$config['admin_password_hash']))throw new InvalidArgumentException('Incorrect username or password.');
 session_regenerate_id(true);$_SESSION['authenticated']=true;$_SESSION['csrf']=bin2hex(random_bytes(32));header('Location: ./');exit;
 }
 elseif(empty($_SESSION['authenticated'])){http_response_code(401);throw new InvalidArgumentException('Please sign in.');}
 elseif($action==='logout'){$_SESSION=[];session_destroy();setcookie('unique_crm','',['expires'=>time()-3600,'path'=>'/customer-register/','secure'=>$config['secure_cookies']??true,'httponly'=>true,'samesite'=>'Strict']);header('Location: ./');exit;}
 elseif($action==='add'){$result=saveEnquiry($_POST,(string)($_POST['source']??''),(string)($_POST['submissionId']??''));header('Location: ./?customer='.$result['customer_id']);exit;}
 elseif($action==='status'){if(!in_array($_POST['status']??'',STATUSES,true))throw new InvalidArgumentException('Invalid status.');$notes=field($_POST,'notes',5000);query('UPDATE enquiries SET status=?,staff_notes=?,updated_at=? WHERE id=?',[$_POST['status'],$notes,now(),(int)($_POST['id']??0)]);$notice='Enquiry updated.';}
 elseif($action==='edit'){
 $c=customerData(array_merge($_POST,['service'=>'Other / please advise','details'=>'Customer update']));query('UPDATE customers SET name=?,phone=?,email=?,company=?,area=?,marketing=?,updated_at=? WHERE id=?',[$c['name'],$c['phone'],$c['email'],$c['company'],$c['area'],(int)$c['marketing'],now(),(int)$_POST['id']]);$notice='Customer updated.';
 }
 elseif($action==='export'){
 header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="unique-customers-'.gmdate('Y-m-d').'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");
 $type=$_POST['type']??'customers';
 if($type==='areas'){$cols=['Area','Segment','Customers'];$data=query("SELECT area,CASE WHEN company='' THEN 'Individual' ELSE 'Business' END AS segment,COUNT(*) AS customers FROM customers GROUP BY area,CASE WHEN company='' THEN 'Individual' ELSE 'Business' END ORDER BY customers DESC");}
 elseif($type==='enquiries'){$cols=['Reference','Name','Mobile','Area','Service','Source','Status','Enquiry','Staff notes','Offers opt-in','Created UTC','Updated UTC'];$data=query('SELECT e.id,c.name,c.phone,c.area,e.service,e.source,e.status,e.details,e.staff_notes,e.marketing,e.created_at,e.updated_at FROM enquiries e JOIN customers c ON c.id=e.customer_id ORDER BY e.id DESC');}
 else{$cols=['ID','Name','Mobile','Email','Company','Area','Offers opt-in','Created UTC','Updated UTC'];$data=query('SELECT id,name,phone,email,company,area,marketing,created_at,updated_at FROM customers ORDER BY id DESC');}
 fputcsv($out,$cols);while($row=$data->fetch())fputcsv($out,array_map('csvCell',array_values($row)));fclose($out);exit;
 }
 }
}catch(InvalidArgumentException|OverflowException $e){$error=$e->getMessage();}
catch(PDOException $e){$error=$e->getCode()==='23000'?'That mobile number already belongs to another customer.':'Unable to save. Please try again.';}
catch(Throwable $e){$error='Unable to complete this action. Please try again.';}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Unique Tailoring | Customer register</title><link rel="stylesheet" href="admin.css"></head><body><main><header><div><small>UNIQUE TAILORING DUBAI · PRIVATE</small><h1>Customer register</h1></div><?php if(!empty($_SESSION['authenticated'])): ?><form method="post"><?=csrf()?><input type="hidden" name="action" value="logout"><button>Sign out</button></form><?php endif;?></header>
<?php if($error):?><p class="error" role="alert"><?=h($error)?></p><?php endif;?><?php if($notice):?><p class="success" role="status"><?=h($notice)?></p><?php endif;?>
<?php if(empty($_SESSION['authenticated'])): ?><section class="login"><h2>Owner sign-in</h2><p>Customer details are accessible only after signing in.</p><form method="post"><?=csrf()?><input type="hidden" name="action" value="login"><label>Username<input name="username" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><button>Sign in</button></form></section>
<?php else:
 $tot=(int)query('SELECT COUNT(*) FROM customers')->fetchColumn();$open=(int)query("SELECT COUNT(*) FROM enquiries WHERE status<>'Completed'")->fetchColumn();
?><nav><a href="./">All customers</a><a href="#add">Add enquiry</a><a href="#area-report">Area report</a></nav><div class="metrics"><section><strong><?=$tot?></strong> customers</section><section><strong><?=$open?></strong> open enquiries</section></div>
<section><h2>Find customers</h2><form method="get" class="filters"><?=input('q','Name, mobile, company or email',$search)?><label>Area<select name="area"><option value="">All areas</option><?=options(query('SELECT DISTINCT area FROM customers ORDER BY area')->fetchAll(PDO::FETCH_COLUMN),$area)?></select></label><label>Enquiry status<select name="status"><option value="">All statuses</option><?=options(STATUSES,$status)?></select></label><button>Search</button></form>
<?php $where=[];$args=[];if($search!==''){$where[]='(c.name LIKE ? OR c.phone LIKE ? OR c.company LIKE ? OR c.email LIKE ?)';for($i=0;$i<4;$i++)$args[]='%'.$search.'%';}if($area!==''){$where[]='c.area=?';$args[]=$area;}if(in_array($status,STATUSES,true)){$where[]='EXISTS(SELECT 1 FROM enquiries e WHERE e.customer_id=c.id AND e.status=?)';$args[]=$status;}$sql=$where?' WHERE '.implode(' AND ',$where):'';$page=max(1,(int)($_GET['page']??1));$offset=($page-1)*50;$matches=(int)query('SELECT COUNT(*) FROM customers c'.$sql,$args)->fetchColumn();$people=query('SELECT c.*,(SELECT COUNT(*) FROM enquiries e WHERE e.customer_id=c.id) AS enquiries FROM customers c'.$sql.' ORDER BY c.updated_at DESC LIMIT 50 OFFSET '.$offset,$args)->fetchAll(); ?>
<p><?=h($matches)?> matching customers · page <?=h($page)?></p><div class="table"><table><thead><tr><th>Customer</th><th>Mobile</th><th>Company / segment</th><th>Area</th><th>Enquiries</th></tr></thead><tbody><?php foreach($people as $p):?><tr><td><a href="?customer=<?=$p['id']?>"><?=h($p['name'])?></a><small><?=h($p['email'])?></small></td><td><?=h($p['phone'])?></td><td><?=h($p['company']?:'Individual')?></td><td><?=h($p['area'])?></td><td><?=$p['enquiries']?></td></tr><?php endforeach;?></tbody></table></div><p><?php if($page>1):?><a href="?<?=h(http_build_query(['q'=>$search,'area'=>$area,'status'=>$status,'page'=>$page-1]))?>">Previous</a> <?php endif;?><?php if($offset+50<$matches):?><a href="?<?=h(http_build_query(['q'=>$search,'area'=>$area,'status'=>$status,'page'=>$page+1]))?>">Next</a><?php endif;?></p></section>
<?php if($customerId&&($p=query('SELECT * FROM customers WHERE id=?',[$customerId])->fetch())): ?><section id="customer"><h2><?=h($p['name'])?> · enquiry history</h2><details><summary>Edit contact details</summary><form method="post" class="grid"><?=csrf()?><input type="hidden" name="action" value="edit"><input type="hidden" name="id" value="<?=$customerId?>"><?=input('name','Full name *',$p['name'],true)?><?=input('phone','Mobile *',$p['phone'],true,'tel',24)?><?=input('email','Email',$p['email'],false,'email',254)?><?=input('company','Company',$p['company'])?><?=input('area','Area / community *',$p['area'],true)?><label class="check"><input type="checkbox" name="marketing" value="yes" <?=$p['marketing']?'checked':''?>>Offers opt-in (only with permission)</label><button>Save customer</button></form></details>
<?php $historyPage=max(1,(int)($_GET['history_page']??1));$historyOffset=($historyPage-1)*20;$historyCount=(int)query('SELECT COUNT(*) FROM enquiries WHERE customer_id=?',[$customerId])->fetchColumn();foreach(query('SELECT * FROM enquiries WHERE customer_id=? ORDER BY id DESC LIMIT 20 OFFSET '.$historyOffset,[$customerId]) as $e):?><article><h3>UT-<?=str_pad((string)$e['id'],6,'0',STR_PAD_LEFT)?> · <?=h($e['service'])?></h3><p><?=h($e['source'])?> · <?=h($e['created_at'])?> UTC · Offers opt-in at enquiry: <?=$e['marketing']?'Yes':'No'?></p><pre><?=h($e['details'])?></pre><details><summary>Contact details at submission</summary><pre><?=h(json_encode(json_decode($e['snapshot_json'],true),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE))?></pre></details><form method="post"><?=csrf()?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$e['id']?>"><label>Status<select name="status"><?=options(STATUSES,$e['status'])?></select></label><label>Private staff notes<textarea name="notes" maxlength="5000" rows="3"><?=h($e['staff_notes'])?></textarea></label><button>Update enquiry</button></form></article><?php endforeach;?>
<p><?php if($historyPage>1):?><a href="?customer=<?=$customerId?>&amp;history_page=<?=$historyPage-1?>">Newer enquiries</a><?php endif;?> <?php if($historyOffset+20<$historyCount):?><a href="?customer=<?=$customerId?>&amp;history_page=<?=$historyPage+1?>">Older enquiries</a><?php endif;?></p></section><?php endif;?>
<section id="area-report"><h2>Customers by area and segment</h2><p>Counts unique mobile numbers. Business means a company name is recorded. Repeat enquiries do not add another customer. Area reflects the latest customer details; “Other” areas may need standardising in Edit contact details.</p><div class="table"><table><tr><th>Area</th><th>Segment</th><th>Customers</th></tr><?php foreach(query("SELECT area,CASE WHEN company='' THEN 'Individual' ELSE 'Business' END AS segment,COUNT(*) AS total FROM customers GROUP BY area,CASE WHEN company='' THEN 'Individual' ELSE 'Business' END ORDER BY total DESC,area") as $r):?><tr><td><?=h($r['area'])?></td><td><?=h($r['segment'])?></td><td><?=h($r['total'])?></td></tr><?php endforeach;?></table></div></section>
<section id="add"><h2>Add a customer enquiry</h2><p>Record phone, WhatsApp, email and shop enquiries here. They are not imported automatically. Matching mobile numbers share one customer record.</p><form method="post" class="grid"><?=csrf()?><input type="hidden" name="action" value="add"><input type="hidden" name="submissionId" value="<?=h(sprintf('%s-%s-%s-%s-%s',bin2hex(random_bytes(4)),bin2hex(random_bytes(2)),bin2hex(random_bytes(2)),bin2hex(random_bytes(2)),bin2hex(random_bytes(6))))?>"><?=input('name','Full name *','',true)?><?=input('phone','Mobile / WhatsApp *','',true,'tel',24)?><?=input('email','Email','',false,'email',254)?><?=input('company','Company (required for corporate uniforms)')?><?=input('area','Area / community *','',true)?><label>Service *<select name="service" required><?=options(SERVICES)?></select></label><label>Source *<select name="source" required><?=options(array_values(array_diff(SOURCES,['Website'])))?></select></label><label class="wide">Enquiry details *<textarea name="details" required maxlength="18000" rows="4"></textarea></label><label class="check"><input type="checkbox" name="marketing" value="yes"> Customer agreed to receive offers</label><button>Save enquiry</button></form></section>
<section><h2>Export for Excel</h2><p>Exports include all records. Keep downloaded files private.</p><form method="post" class="filters"><?=csrf()?><input type="hidden" name="action" value="export"><label>Report<select name="type"><option value="customers">Customer list</option><option value="enquiries">Enquiry history</option><option value="areas">Area and segment totals</option></select></label><button>Download CSV</button></form></section><p>Times are stored in UTC (Dubai: UTC +4). Sign-in expires after 30 minutes of inactivity.</p>
<?php endif;?></main></body></html>
